@spec generators_spec  src=tests/specs/generators_spec.lua  loc=483  sha=a17676d  cases=31
@exercises generators (generators), tuning (tuning)
@surface   generators.retarget, generators.fieldRange, tuning.findTemper, tuning.transposeStep, tuning.stepsBetween

# Intent
  generators.lua: slide glide-in envelope.

# Helpers
  @fn expand(kind, hostRec, params, ctx)  @ 9-11
      -- Kinds run alone here, so the chain state equals the original: stream == host (the chain head).
  @fn slideCtx(nextNote, pbRangeCents)  @ 14-17
      -- A slide host (pitch 60) and a ctx supplying the next same-lane note + pb ceiling.
  @fn slideHost(detune)  @ 18-20
  @fn triangle()  @ 24-30
      -- A loop-closed triangle in the normalized domain (-1 .. +1 .. -1), one QN long.

# Cases
  @case 'slide glides in: flat hold, slur to the interval, re-centre at the window end'  [pure]  @ 37-48
  @case 'slide interval includes detune (the microtonal offset rides in detune, not pitch)'  [pure]  @ 52-56
  @case 'slide clamps the target to ctx.pbRangeCents (a pb can only bend so far)'  [pure]  @ 60-64
  @case 'slide.target='fixed' is a fixed-cents bend (cents demand, no next-note lookup)'  [pure]  @ 68-73
  @case 'slide.target='next' with no following note yields no delta (carrier untouched)'  [pure]  @ 77-81
  @case 'slide to a unison next note yields no delta (zero interval)'  [pure]  @ 85-89
  @case 'trill tiles the window from its start, alternating host pitch with the stepped note'  [pure]  @ 95-111
  @case 'trill carries host detune verbatim on the return (even) tiles'  [pure]  @ 115-122
  @case 'parksNotes is true for any note-dest kind, false for a continuous kind / husk'  [pure]  @ 128-133
  @case 'parkWindows emits an evType-tagged window per continuous/replace target (note discrete, cc, pb augment)'  [pure]  @ 137-152
  @case 'destOf falls back to the registry dest; a dest param overrides it'  [pure]  @ 158-163
  @case 'fieldsFor prepends a Dest row only where the kind can serve more than one target'  [pure]  @ 167-175
  @case 'retarget between dests of equal reference leaves the magnitudes alone'  [pure]  @ 179-184
  @case 'retarget rescales magnitudes by proportion of the dest reference'  [pure]  @ 188-194
  @case 'fieldRange spans both ways for a signed magnitude, one way for an unsigned one'  [pure]  @ 198-204
  @case 'retarget carries a signed magnitude across with its sign intact'  [pure]  @ 208-214
  @case 'parkWindows follows the dest param, not the registry (a retargeted pb kind parks cc)'  [pure]  @ 218-225
  @case 'sine on a cc dest tiles the window with extrema in cc steps, anchored 0 at both ends'  [pure]  @ 231-244
  @case 'velPattern cycles its percent pattern per distinct onset; a chord shares one step'  [pure]  @ 250-265
  @case 'velPattern walks onset order regardless of input order, clamping vel to 1..127'  [pure]  @ 269-279
  @case 'ostinato tracks the sounding pitch across the region, not just the first note'  [pure]  @ 285-297
  @case 'ostinato rests when no region note sounds at the gate onset'  [pure]  @ 301-310
  @case 'ostinato emits one gated note per sounding voice (a chord -> multiple lanes)'  [pure]  @ 314-325
  @case 'chord-stamp rebases the pattern chord onto each member; lane-1 note lands on the trigger'  [pure]  @ 331-354
  @case 'chord-stamp transposes by whole temper steps through ctx, not by raw pitch'  [pure]  @ 358-377
  @case 'chord-stamp fires a chord on every region member (all lanes are triggers)'  [pure]  @ 381-403
  @case 'chord-stamp with no lane-1 note in the pattern is inert (no root to rebase from)'  [pure]  @ 407-418
  @case 'lfo tiles the curve at 1/period QN, mapping each val by offset + scale, edges seeded'  [pure]  @ 424-441
  @case 'lfo maps norm in whatever units the dest counts in -- cents on pb'  [pure]  @ 445-454
  @case 'lfo does not clamp -- the body holds no dest knowledge, and the cc seat clamps'  [pure]  @ 458-467
  @case 'lfo with an empty or lengthless curve is inert (no delta)'  [pure]  @ 471-480

